mapper.select:
select
FROM REP_RAISE_SUM R LEFT JOIN FIN_PRODUCT F ON R.REP_FINPROD_ID = F.FINPROD_ID LEFT JOIN REP_PROD_DECLARE RPD on RPD.REP_FINPROD_ID = R.REP_FINPROD_ID
AND F.FINPROD_MARKET_ID IN
#{item}
AND R.REP_FINPROD_ID IN
#{item}
AND R.REP_FINPROD_REG_ID LIKE CONCAT('%',CONCAT(#{registrationCode},'%'))
AND RPD.REP_INVESTOR_TYPE = #{customerType}
AND F.VDATE BETWEEN TO_DATE(#{startDateStart},'YYYY-MM-DD') AND TO_DATE(#{startDateEnd},'YYYY-MM-DD')
AND R.REP_STATUS_DATE BETWEEN TO_DATE(#{dataDateStart},'YYYY-MM-DD') AND TO_DATE(#{dateDateEnd},'YYYY-MM-DD')
